import assert from 'node:assert/strict';
import { Router } from '../src/http/router.ts';
import { orderRoutes } from '../src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from '../src/orders/integration/order-store.ts';
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
const order = (id, customerId='u', status='pending', items=['x']) => ({id,customerId,status,items});
function setup(seed=[order('s','u','pending',['b','a','b']),order('t','u','pending',['z']),order('other')]) {
 const orders=new InMemoryOrderStore(seed); let writes=0;
 const save=orders.save.bind(orders); orders.save=o=>{writes++;save(o)};
 const router=orderRoutes(new Router(),{orders,sessions:{lookup:t=>t==='ok'?{id:'u'}:undefined}});
 return {orders,router,get writes(){return writes},call:(body:any={sourceId:'s',targetId:'t'},authorization:any='Bearer ok')=>router.handle({method:'POST',path:'/orders/merge',headers:{authorization},body})};
}
function reject(f,body:any={sourceId:'s',targetId:'t'},auth:any='Bearer ok') {
 const before=structuredClone(f.orders.all()); const r=f.call(body,auth);
 assert.ok(r.status>=400&&r.status<500,`expected 4xx, got ${r.status}`); assert.deepEqual(f.orders.all(),before); assert.equal(f.writes,0);
}
let f=setup(); const unrelated=structuredClone(f.orders.get('other')); const original=f.orders.get('t').items;
assert.equal(f.call().status,200); assert.deepEqual(f.orders.get('t'),order('t','u','pending',['z','b','a','b'])); assert.equal(f.orders.get('s').status,'cancelled'); assert.deepEqual(f.orders.get('other'),unrelated); assert.deepEqual(original,['z']);
console.log('R1/R6 success: exact ordered duplicates, identity, source cancellation, unrelated orders, no original-array mutation');
for(const auth of ['', 'Bearer wrong','Basic ok','Bearer ']) reject(setup(),{sourceId:'s',targetId:'t'},auth);
console.log('R2: missing/invalid/inappropriate authentication: no writes');
for(const owners of [['v','u'],['u','v'],['v','v']]) reject(setup([order('s',owners[0]),order('t',owners[1])]));
console.log('R3: source-only, target-only, both foreign rejected without writes');
for(const id of ['s','t']) { reject(setup([order(id)])); for(const status of ['shipped','cancelled']) reject(setup([order('s','u',id==='s'?status:'pending'),order('t','u',id==='t'?status:'pending')])); }
f=setup();f.call();const before=structuredClone(f.orders.all());assert.equal(f.call().status,409);assert.deepEqual(f.orders.all(),before);assert.equal(f.writes,2);
console.log('R4/R6: missing/state failures and replay unchanged');
for(const body of [null, false, 4, 'text', [], {}, {sourceId:'s'}, {sourceId:1,targetId:'t'}, {sourceId:'s',targetId:[]}, {sourceId:'',targetId:'t'}, {sourceId:'s',targetId:''}, {sourceId:'s',targetId:'s'}]) reject(setup(),body);
console.log('R5: ordinary malformed/empty/missing/self requests rejected');
f=setup([order(''),order('t')]); const empty=f.call({sourceId:'',targetId:'t'});console.log('R5 empty identifier with stored empty ID:',empty.status,'writes:',f.writes);
for(const [path,expected] of [['src/orders/domain/order.ts','553509c'],['src/orders/routes/order-routes.ts','36a4455']]) {const b=readFileSync(path); const h=createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex');assert.ok(h.startsWith(expected)); assert.ok(!/process\.env|node:test|tests\/|o1|o2/.test(b.toString()));}
console.log('R7: allowed files match supplied diff postimage hashes; no test detection/witness IDs; supplied full diff contains only allowed paths');
EOF
node evaluator/independent-probes.ts
